CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE countries (code char(2) PRIMARY KEY, name text NOT NULL, timezone text NOT NULL, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE currencies (code char(3) PRIMARY KEY, minor_digits int NOT NULL CHECK(minor_digits BETWEEN 0 AND 3));
CREATE TABLE cities (id uuid PRIMARY KEY, country_code char(2) NOT NULL REFERENCES countries, name text NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), timezone text NOT NULL, UNIQUE(country_code,name));
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, email_verified_at timestamptz, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users, display_name text NOT NULL, bio text NOT NULL DEFAULT '', avatar_url text, city_id uuid REFERENCES cities, interests text[] NOT NULL DEFAULT '{}', visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','private')), show_attendance boolean NOT NULL DEFAULT true, show_location boolean NOT NULL DEFAULT true, compete boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid REFERENCES users, role text CHECK(role IN ('USER','ORGANIZER','ADMIN')), PRIMARY KEY(user_id,role));
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_tokens (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, token_hash text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('verify','reset')), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE follows (follower_id uuid REFERENCES users, following_id uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,following_id), CHECK(follower_id<>following_id));
CREATE TABLE blocks (blocker_id uuid REFERENCES users, blocked_id uuid REFERENCES users, PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
CREATE TABLE event_categories (slug text PRIMARY KEY, name text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE organizer_applications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, name text NOT NULL, category text NOT NULL REFERENCES event_categories, description text NOT NULL, city_id uuid NOT NULL REFERENCES cities, contact_email text NOT NULL, phone text NOT NULL, social_url text, verification_info text NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','under_review','approved','rejected','suspended')), review_note text, reviewed_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_application ON organizer_applications(user_id) WHERE status IN ('submitted','under_review','approved');
CREATE TABLE communities (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL, city_id uuid NOT NULL REFERENCES cities, category text NOT NULL REFERENCES event_categories, cover_url text, logo_url text, verified boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), application_id uuid UNIQUE REFERENCES organizer_applications, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizer_members (community_id uuid REFERENCES communities, user_id uuid REFERENCES users, PRIMARY KEY(community_id,user_id));
CREATE TABLE community_follows (community_id uuid REFERENCES communities, user_id uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(community_id,user_id));
CREATE TABLE events (id uuid PRIMARY KEY, community_id uuid NOT NULL REFERENCES communities, created_by uuid NOT NULL REFERENCES users, title text NOT NULL, description text NOT NULL, category text NOT NULL REFERENCES event_categories, difficulty text NOT NULL CHECK(difficulty IN ('beginner','intermediate','advanced','all')), city_id uuid NOT NULL REFERENCES cities, location_name text NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity int NOT NULL CHECK(capacity BETWEEN 1 AND 100000), price_minor int NOT NULL CHECK(price_minor BETWEEN 0 AND 100000000), currency char(3) NOT NULL REFERENCES currencies, cover_url text, tags text[] NOT NULL DEFAULT '{}', requirements text NOT NULL DEFAULT '', included text NOT NULL DEFAULT '', safety_info text NOT NULL, cancellation_hours int NOT NULL DEFAULT 24 CHECK(cancellation_hours>=0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','cancelled','completed')), featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE INDEX events_discovery ON events(status,starts_at,city_id,category);
CREATE INDEX events_location ON events(latitude,longitude);
CREATE INDEX events_title_search ON events USING gin(to_tsvector('simple',title || ' ' || description));
CREATE TABLE event_media (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events, url text NOT NULL, kind text NOT NULL CHECK(kind IN ('image','video')), position int NOT NULL DEFAULT 0);
CREATE TABLE platform_fee_rules (id uuid PRIMARY KEY, country_code char(2) NOT NULL REFERENCES countries, currency char(3) NOT NULL REFERENCES currencies, fixed_minor int NOT NULL CHECK(fixed_minor>=0), basis_points int NOT NULL CHECK(basis_points BETWEEN 0 AND 10000), enabled boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_code,currency));
CREATE TABLE bookings (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, event_id uuid NOT NULL REFERENCES events, status text NOT NULL CHECK(status IN ('reserved','confirmed','cancelled','expired','refund_pending','refunded')), ticket_minor int NOT NULL CHECK(ticket_minor>=0), fee_minor int NOT NULL CHECK(fee_minor>=0), total_minor int NOT NULL CHECK(total_minor=ticket_minor+fee_minor), currency char(3) NOT NULL REFERENCES currencies, idempotency_key text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz, cancelled_at timestamptz, UNIQUE(user_id,idempotency_key));
CREATE UNIQUE INDEX one_active_booking ON bookings(user_id,event_id) WHERE status IN ('reserved','confirmed');
CREATE INDEX bookings_capacity ON bookings(event_id,status,expires_at);
CREATE TABLE booking_items (id uuid PRIMARY KEY, booking_id uuid NOT NULL REFERENCES bookings, description text NOT NULL, amount_minor int NOT NULL CHECK(amount_minor>=0), kind text NOT NULL CHECK(kind IN ('ticket','service_fee')));
CREATE TABLE payments (id uuid PRIMARY KEY, booking_id uuid NOT NULL UNIQUE REFERENCES bookings, provider text NOT NULL, provider_reference text UNIQUE, checkout_url text, amount_minor int NOT NULL, currency char(3) NOT NULL REFERENCES currencies, status text NOT NULL CHECK(status IN ('created','pending','paid','failed','refund_pending','refunded')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (provider text NOT NULL, external_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,external_id));
CREATE TABLE refunds (id uuid PRIMARY KEY, booking_id uuid NOT NULL UNIQUE REFERENCES bookings, payment_id uuid NOT NULL REFERENCES payments, amount_minor int NOT NULL CHECK(amount_minor>0), status text NOT NULL CHECK(status IN ('pending','processing','succeeded','failed')), provider_reference text, reason text NOT NULL, attempts int NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payouts (id uuid PRIMARY KEY, community_id uuid NOT NULL REFERENCES communities, amount_minor int NOT NULL CHECK(amount_minor>0), currency char(3) NOT NULL REFERENCES currencies, status text NOT NULL CHECK(status IN ('pending','processing','paid','failed')), provider_reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payout_items (payout_id uuid REFERENCES payouts, booking_id uuid UNIQUE REFERENCES bookings, amount_minor int NOT NULL, PRIMARY KEY(payout_id,booking_id));
CREATE TABLE tickets (id uuid PRIMARY KEY, booking_id uuid NOT NULL UNIQUE REFERENCES bookings, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE checkins (id uuid PRIMARY KEY, ticket_id uuid NOT NULL UNIQUE REFERENCES tickets, event_id uuid NOT NULL REFERENCES events, user_id uuid NOT NULL REFERENCES users, checked_in_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id));
CREATE TABLE xp_rules (source text PRIMARY KEY, points int NOT NULL CHECK(points BETWEEN 0 AND 10000), enabled boolean NOT NULL DEFAULT true);
CREATE TABLE xp_transactions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, source_type text NOT NULL, source_id uuid NOT NULL, points int NOT NULL CHECK(points BETWEEN -100000 AND 100000), idempotency_key text NOT NULL UNIQUE, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX xp_ranking ON xp_transactions(created_at,user_id) INCLUDE(points);
CREATE INDEX xp_user ON xp_transactions(user_id,created_at);
CREATE FUNCTION immutable_xp() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'XP ledger is append-only; use a compensating transaction'; END $$;
CREATE TRIGGER xp_no_mutation BEFORE UPDATE OR DELETE ON xp_transactions FOR EACH ROW EXECUTE FUNCTION immutable_xp();
CREATE TABLE challenges (id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, kind text NOT NULL CHECK(kind IN ('attendance','category','explorer','streak')), category text REFERENCES event_categories, target int NOT NULL CHECK(target>0), reward_xp int NOT NULL CHECK(reward_xp BETWEEN 0 AND 10000), badge text NOT NULL, enabled boolean NOT NULL DEFAULT true, CHECK(ends_at>starts_at));
CREATE TABLE challenge_participants (challenge_id uuid REFERENCES challenges, user_id uuid REFERENCES users, joined_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, PRIMARY KEY(challenge_id,user_id));
CREATE TABLE achievements (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL, kind text NOT NULL CHECK(kind IN ('attendance','explorer','early','night','streak','ranking')), threshold int NOT NULL CHECK(threshold>0), badge text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE user_achievements (user_id uuid REFERENCES users, achievement_id uuid REFERENCES achievements, unlocked_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,achievement_id));
CREATE TABLE seasons (id uuid PRIMARY KEY, name text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE leaderboard_snapshots (user_id uuid REFERENCES users, scope text NOT NULL, period text NOT NULL, snapshot_date date NOT NULL, rank int NOT NULL, score bigint NOT NULL, PRIMARY KEY(user_id,scope,period,snapshot_date));
CREATE TABLE notifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, title text NOT NULL, body text NOT NULL, link text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notification_inbox ON notifications(user_id,created_at DESC);
CREATE TABLE device_tokens (token text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, platform text NOT NULL CHECK(platform IN ('ios','android')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox (id uuid PRIMARY KEY, notification_id uuid REFERENCES notifications, payload jsonb NOT NULL, kind text NOT NULL CHECK(kind IN ('push','email')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed')), attempts int NOT NULL DEFAULT 0, last_error text, available_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY, reporter_id uuid NOT NULL REFERENCES users, target_type text NOT NULL CHECK(target_type IN ('event','user','community')), target_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','dismissed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions (id uuid PRIMARY KEY, report_id uuid REFERENCES reports, admin_id uuid NOT NULL REFERENCES users, action text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reactions (user_id uuid REFERENCES users, checkin_id uuid REFERENCES checkins, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,checkin_id));
CREATE TABLE recent_searches (user_id uuid REFERENCES users, term text NOT NULL, searched_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,term));
CREATE TABLE analytics_events (id uuid PRIMARY KEY, user_id uuid REFERENCES users, event_id uuid REFERENCES events, name text NOT NULL CHECK(name IN ('event_view','share','checkout_started')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, target_type text NOT NULL, target_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER audit_no_mutation BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_xp();
